import assert from "node:assert/strict";

function readQuantity(input: { qty?: number | null }): number {
  const qty = typeof input.qty === "number" && !Number.isNaN(input.qty) ? input.qty : 1;
  return qty;
}

assert.equal(readQuantity({ qty: 0 }), 0);
assert.equal(readQuantity({ qty: undefined }), 1);
assert.equal(readQuantity({ qty: Number.NaN }), 1);
